{"query":"query($fl:Float!,$fp:Float!,$tl:Float!,$tp:Float!,$dt:DateTime,$arr:Boolean,$n:Int!,$walk:Float!,$wheel:Boolean!,$xfer:Int!){
  trip(from:{coordinates:{latitude:$fl,longitude:$fp}},to:{coordinates:{latitude:$tl,longitude:$tp}},
       numTripPatterns:$n,dateTime:$dt,arriveBy:$arr,walkSpeed:$walk,wheelchairAccessible:$wheel,transferPenalty:$xfer){
    tripPatterns{expectedStartTime expectedEndTime duration walkDistance legs{
      mode distance duration expectedStartTime expectedEndTime
      fromPlace{name quay{publicCode latitude longitude}}
      toPlace{name quay{publicCode latitude longitude}}
      line{publicCode}
